import { Component, Prop, Emit } from 'vue-property-decorator';
import { PersistentSettingComponent } from '../../common/persistent-setting';
import SettingsMenuItem from '../../settings-menu/item/index.vue';
import { UserPreferences } from '../../../user-preferences';
import { SettingsEventEmitter } from '../../../event-emitter';
import { ISettingsOption } from '../../../types';

@Component({
    name: 'SettingsItemRadioButton',
    components: {
        SettingsMenuItem
    }
})
export default class SettingsItemRadioButton extends PersistentSettingComponent<string | number> {
    @Prop({
        type: String,
        required: true
    })
    public label: string;

    @Prop({
        type: Array,
        required: true
    })
    public options!: Array<ISettingsOption>;

    public override value = UserPreferences.getPreference(this.prefKey, this.default, this.isMisc, this.isGlobal, this.options);

    @Emit('onChange')
    public onChange(value: ISettingsOption) {
        this.value = value.value;
        return this.value;
    }

    public mounted(): void {
        SettingsEventEmitter.on('show', this.updateValue, this);
    }

    public destroy(): void {
        SettingsEventEmitter.off('show', this.updateValue, this);
    }

    public updateValue(): void {
        this.value = UserPreferences.getPreference(this.prefKey, this.default, this.isMisc, this.isGlobal, this.options);
    }
}
